<script setup lang="ts">
import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { getTool } from '../registry'; import { decodeUrl, encodeUrl, type UrlMode } from './url'
const {t}=useI18n();const tool=getTool('soc-tools.url');const input=ref('');const output=ref('');const error=ref('');const operation=ref<'encode'|'decode'>('encode');const mode=ref<UrlMode>('component');const copied=ref(false);const inputBytes=computed(()=>new TextEncoder().encode(input.value).byteLength);const isOverLimit=computed(()=>inputBytes.value>tool.recommendedMaxInputBytes)
function transform(){error.value='';copied.value=false;if(!input.value){output.value='';return}try{output.value=operation.value==='encode'?encodeUrl(input.value,mode.value):decodeUrl(input.value,mode.value)}catch{output.value='';error.value=t('tools.url.invalid')}}function clear(){input.value='';output.value='';error.value='';copied.value=false}async function copyOutput(){if(output.value){await navigator.clipboard.writeText(output.value);copied.value=true}}
</script>
<template><section class="tool-page" aria-labelledby="tool-title"><header class="tool-heading"><span class="category">{{ t(`categories.${tool.category}`) }}</span><h1 id="tool-title">{{ t(tool.nameKey) }}</h1><p>{{ t(tool.descriptionKey) }}</p></header><div class="io-panel"><div class="terminal-titlebar"><span class="window-marks" aria-hidden="true"><i /><i /><i /></span><span>[ url ]</span></div><div class="io-strip"><fieldset><legend>{{ t('common.operation') }}</legend><label class="radio-control"><input v-model="operation" type="radio" value="encode" @change="transform"><span>{{ t('common.encode') }}</span></label><label class="radio-control"><input v-model="operation" type="radio" value="decode" @change="transform"><span>{{ t('common.decode') }}</span></label></fieldset><span class="strip-divider" aria-hidden="true" /><fieldset><legend>{{ t('tools.url.mode') }}</legend><label class="radio-control"><input v-model="mode" type="radio" value="component" @change="transform"><span>{{ t('tools.url.component') }}</span></label><label class="radio-control"><input v-model="mode" type="radio" value="full" @change="transform"><span>{{ t('tools.url.full') }}</span></label></fieldset><span class="byte-count">{{ inputBytes }} B</span><div class="strip-actions"><button class="icon-button" type="button" :disabled="!output" :aria-label="copied?t('common.copied'):t('common.copy')" @click="copyOutput"><svg aria-hidden="true" viewBox="0 0 24 24"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M15 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h3" /></svg></button><button class="icon-button" type="button" :aria-label="t('common.clear')" @click="clear"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14" /></svg></button></div></div><p v-if="isOverLimit" class="notice warning" role="status">{{ t('common.warning',{size:'1 MB'}) }}</p><div class="editor-grid"><div class="field"><label for="url-input"><span>$</span> {{ t('common.input') }}</label><div class="terminal-editor input-editor"><span class="editor-prompt" aria-hidden="true">$</span><textarea id="url-input" v-model="input" :class="{invalid:error}" :aria-invalid="Boolean(error)" :aria-describedby="error?'url-error':undefined" :placeholder="t('tools.url.placeholder')" spellcheck="false" @input="transform" /></div></div><div class="field"><label for="url-output"><span>&gt;</span> {{ t('common.output') }}</label><div class="terminal-editor"><span class="editor-prompt" aria-hidden="true">&gt;</span><textarea id="url-output" :value="output" :placeholder="t('common.result')" readonly /></div></div></div><p v-if="error" id="url-error" class="notice error" role="alert">{{ error }}</p></div></section></template>
